// Asset imports are strings (file URLs/paths, or text when configured by the loader).
// These declarations only provide types; configure the bundler to load each format.
// Keep this file free of top-level imports/exports so these stay ambient modules.
// JSON is intentionally omitted: use compilerOptions.resolveJsonModule for inferred types.

// Stylesheets
declare module "*.css" {
  const asset: string;
  export default asset;
}

declare module "*.scss" {
  const asset: string;
  export default asset;
}

